import { corsHeadersForRequest, isAllowedBrowserOrigin } from "./origin-policy.js";
import { parseWebRtcStatsSessionId, WebRtcSignalingError } from "./webrtc-signaling.js";
const MAX_DEVICE_SERIAL_BYTES = 256;
export class WebRtcStatsRequestError extends Error {
    code;
    status;
    constructor(message, code, status = 400){
        super(message), this.code = code, this.status = status;
        this.name = "WebRtcStatsRequestError";
    }
}
/**
 * Own capture accounting and viewer-scoped report assembly for one source.
 * A missing or zero-peer delivery means no viewer was offered the source frame.
 */ export class WebRtcStatsCollector {
    now;
    #offeredFrames = 0;
    #forwardedFrames = 0;
    constructor(now = Date.now){
        this.now = now;
    }
    recordDelivery(delivery) {
        if (!delivery || !delivery.accepted && !delivery.awaitingKeyFrame) return;
        this.#offeredFrames++;
        if (delivery.accepted) this.#forwardedFrames++;
    }
    /** Build a narrow report without exposing broad health/session diagnostics. */ report(source, publisher, sessionId, grpcCapture = null) {
        const publisherSession = publisher.statsForSession(sessionId);
        if (!publisherSession) return null;
        return {
            sampledAt: this.now(),
            source: {
                ...source
            },
            sessions: [
                {
                    ...publisherSession
                }
            ],
            capture: {
                offeredFrames: this.#offeredFrames,
                forwardedFrames: this.#forwardedFrames,
                grpc: grpcCapture
            }
        };
    }
}
const errorMessage = (error)=>error instanceof Error ? error.message : String(error);
function statsFailure(code, status, headers, message) {
    return Response.json({
        ok: false,
        error: code,
        ...message ? {
            message
        } : {}
    }, {
        status,
        headers
    });
}
function parseDevice(searchParams) {
    const values = searchParams.getAll("device");
    if (values.length === 0) return null;
    if (values.length !== 1) {
        throw new WebRtcStatsRequestError("Specify exactly one device for WebRTC statistics.", "invalid_device");
    }
    const device = values[0];
    if (device.length === 0 || /[\s\u0000-\u001f\u007f-\u009f]/u.test(device) || new TextEncoder().encode(device).byteLength > MAX_DEVICE_SERIAL_BYTES) {
        throw new WebRtcStatsRequestError(`Device must be a non-empty serial of at most ${MAX_DEVICE_SERIAL_BYTES} bytes without whitespace or control characters.`, "invalid_device");
    }
    return device;
}
/** Serve the package-owned endpoint while keeping idle polling observational. */ export function handleWebRtcStatsRequest(request, policy, readStats, onError = (error)=>console.error(`serve-emu WebRTC stats unavailable: ${errorMessage(error)}`)) {
    const corsHeaders = corsHeadersForRequest(request, policy, "GET, OPTIONS");
    const jsonHeaders = {
        ...corsHeaders,
        "Content-Type": "application/json; charset=utf-8"
    };
    if (!isAllowedBrowserOrigin(request, policy)) {
        return statsFailure("forbidden_origin", 403, jsonHeaders, "Request origin is not allowed for WebRTC statistics.");
    }
    if (request.method === "OPTIONS") {
        return new Response(null, {
            status: 204,
            headers: corsHeaders
        });
    }
    if (request.method !== "GET") {
        return statsFailure("method_not_allowed", 405, jsonHeaders);
    }
    let sessionId;
    let device;
    try {
        const searchParams = new URL(request.url).searchParams;
        const sessionIds = searchParams.getAll("sessionId");
        if (sessionIds.length > 1) {
            throw new WebRtcStatsRequestError("Specify exactly one WebRTC session ID.", "invalid_session_id");
        }
        sessionId = parseWebRtcStatsSessionId(sessionIds[0] ?? null);
        device = parseDevice(searchParams);
    } catch (error) {
        const expected = error instanceof WebRtcSignalingError || error instanceof WebRtcStatsRequestError;
        const status = expected ? error.status : 400;
        const code = expected ? error.code : "invalid_session_id";
        return statsFailure(code, status, jsonHeaders, errorMessage(error));
    }
    try {
        const report = readStats(sessionId, device);
        if (!report) {
            return statsFailure("webrtc_stats_unavailable", 503, jsonHeaders);
        }
        return Response.json(report, {
            headers: jsonHeaders
        });
    } catch (error) {
        if (error instanceof WebRtcStatsRequestError) {
            return statsFailure(error.code, error.status, jsonHeaders, error.message);
        }
        onError(error);
        return statsFailure("webrtc_stats_unavailable", 503, jsonHeaders);
    }
}
